from math import comb
mod = int(1000000000.0 + 7)

def powe(base, exp):
	ans = 1
	while exp:
		if exp & 1:
			ans = ans * base % mod
		base = base * base % mod
		exp //= 2
	return ans

def inverse(base):
	return powe(base, mod - 2)

def handle0(n):
	inte = n % 6
	if n % 6 == 0:
		return 2
	elif inte == 1:
		return 1
	elif inte == 2:
		return -1
	elif inte == 3:
		return -2
	elif inte == 4:
		return -1
	else:
		return 1

def handle1(n):
	inte = n % 6
	if n % 6 == 0:
		return -1
	elif inte == 1:
		return 1
	elif inte == 2:
		return 2
	elif inte == 3:
		return 1
	elif inte == 4:
		return -1
	else:
		return -2

def handle2(n):
	inte = n % 6
	if n % 6 == 0:
		return -1
	elif inte == 1:
		return -2
	elif inte == 2:
		return -1
	elif inte == 3:
		return 1
	elif inte == 4:
		return 2
	else:
		return 1

def solver(a, b):
	a0 = (handle0(a) + powe(2, a)) * inverse(3) % mod
	a1 = (handle1(a) + powe(2, a)) * inverse(3) % mod
	a2 = (handle2(a) + powe(2, a)) * inverse(3) % mod
	b0 = (handle0(b) + powe(2, b)) * inverse(3) % mod
	b1 = (handle1(b) + powe(2, b)) * inverse(3) % mod
	b2 = (handle2(b) + powe(2, b)) * inverse(3) % mod
	print(((a0 * b0 + a1 * b1 + a2 * b2) % mod + mod - 1) % mod)

def main():
	t = int(input())
	while t:
		k = input()
		k = k.split()
		solver(int(k[0]), int(k[1]))
		t -= 1
main()
